export type RequestInput={clearance_slug:string;pressurized_pods:number;vacuum_pods:number;docking_arms:number;solar_flare:boolean};

export const score=(pressurized_pods:number,vacuum_pods:number,docking_arms:number,solar_flare:boolean)=>{
  const payload_tally=pressurized_pods+vacuum_pods;
  const transfer_effort=pressurized_pods*8+vacuum_pods*14+(solar_flare?docking_arms*5:0);
  const berth_allowance=docking_arms*47;
  const approved_effort=Math.min(transfer_effort,berth_allowance);
  const spillover_effort=Math.max(transfer_effort-berth_allowance,0);
  const orbit_passes=Math.ceil(payload_tally/4);
  return approved_effort+spillover_effort*7+orbit_passes*6;
};

export const orbital_clearance_rating=score;

export const calculate=(v:RequestInput)=>{
  const payload_tally=v.pressurized_pods+v.vacuum_pods;
  const transfer_effort=v.pressurized_pods*8+v.vacuum_pods*14+(v.solar_flare?v.docking_arms*5:0);
  const berth_allowance=v.docking_arms*47;
  const approved_effort=Math.min(transfer_effort,berth_allowance);
  const spillover_effort=Math.max(transfer_effort-berth_allowance,0);
  const orbit_passes=Math.ceil(payload_tally/4);
  const clearance_rating=score(v.pressurized_pods,v.vacuum_pods,v.docking_arms,v.solar_flare);
  const clearance_phase=spillover_effort===0?'cleared':v.solar_flare?'flare_hold':'routine_hold';
  return {clearance_slug:v.clearance_slug,payload_tally,transfer_effort,berth_allowance,approved_effort,spillover_effort,orbit_passes,clearance_rating,clearance_phase};
};

export async function loadParley(){return {orbital_clearance_rating:(a0:number,a1:number,a2:number,a3:boolean)=>BigInt(score(a0,a1,a2,a3))}}

